from gl import *
SG = "apcsp/unit-3/unit-3-study-guide.html"
Q = js_array(SG, "Q")
def qs(topic): return [q for q in Q if q["t"] == topic]
def S(cid, title, kick, sel, topic=None, **kw):
    return dict(id=cid, src=("file", SG), title=title, kicker=kick, sel=[sel], nohead=[sel], online=False, questions=qs(topic) if topic else None, **kw)

